{
  "name": "find_shared_free_slot",
  "request_shape": "Find a free one-hour slot next week that works for both Dana Reyes and Sam Okafor, and propose it to them.",
  "inputs": [],
  "steps": [
    {
      "id": "get_dana_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner: Dana Reyes, date_range: next_week"
    },
    {
      "id": "get_sam_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner: Sam Okafor, date_range: next_week"
    },
    {
      "id": "get_contacts",
      "kind": "list",
      "source": "contacts",
      "filter": "name: Dana Reyes OR Sam Okafor"
    },
    {
      "id": "batch_days",
      "kind": "batch",
      "size": 1,
      "inputs": ["get_dana_calendar", "get_sam_calendar"]
    },
    {
      "id": "loop_days",
      "kind": "loop_over_items",
      "over": "batch_days",
      "steps": [
        {
          "id": "find_free_slot",
          "kind": "lookup_via_agent",
          "agent": "calendar",
          "find": "free one-hour slot for Dana Reyes and Sam Okafor on this day"
        }
      ]
    },
    {
      "id": "select_slot",
      "kind": "write",
      "instruction": "Select the first valid free slot found. If none, state 'No common slot found'.",
      "max_words": 20
    },
    {
      "id": "draft_proposal",
      "kind": "write",
      "instruction": "Draft a polite email proposing the selected time slot to Dana Reyes and Sam Okafor.",
      "max_words": 50
    },
    {
      "id": "check_coverage",
      "kind": "check_coverage",
      "rule": "The output must contain a specific time slot and both names if a slot was found, otherwise state no slot found."
    }
  ],
  "output": "draft_proposal"
}

